css:
:root{--u:max(calc(min(100vw,1733px) / 1733),0.62px)}
body{background:#fff;font-family:'Montserrat',sans-serif}
[data-bz-node="header"]{box-sizing:border-box;position:relative;background:linear-gradient(to bottom,rgba(255,255,255,0) 55%,rgba(255,255,255,.55)),url(/camo.jpg) left top/calc(1840 * var(--u)) calc(272 * var(--u)) repeat-x;border-bottom:calc(10 * var(--u)) solid #8f9a96;min-height:calc(272 * var(--u))}
[data-bz-node="header"] .bz-brand{display:block}
[data-bz-node="header"] .bz-logo__img{height:calc(170 * var(--u));width:calc(170 * var(--u));border-radius:50%}
[data-bz-node="hc-addr"],[data-bz-node="hc-people"]{background:#c4a76c;padding:calc(14 * var(--u)) 0 0;height:calc(107 * var(--u));box-sizing:border-box;overflow:hidden}
[data-bz-node="hc-addr"]{padding-left:calc(16 * var(--u));text-align:center}
[data-bz-node="hc-addr-t"] p,[data-bz-node="hc-people-t"] p{margin:0 0 calc(5 * var(--u));line-height:calc(25 * var(--u))}
[data-bz-node="hc-addr-t"] p{font:700 calc(16 * var(--u)) 'Playfair Display',serif;letter-spacing:.08em;text-transform:uppercase;color:#1a1a1a;text-align:center}
[data-bz-node="hc-people-t"] p{font:700 calc(16 * var(--u)) 'Montserrat',sans-serif;text-transform:uppercase;color:#1a1a1a}
[data-bz-node="hc-people-t"] a{color:#1a1a1a;text-decoration:underline}
[data-bz-node="main-nav"] .bz-nav{display:grid;grid-template-columns:repeat(8,1fr);gap:0;width:100%}
[data-bz-node="main-nav"] .bz-navitem{text-align:center;border-left:calc(3 * var(--u)) solid #b0102a;line-height:calc(44 * var(--u))}
[data-bz-node="main-nav"] .bz-navitem:first-child{border-left:0}
[data-bz-node="main-nav"] .bz-navitem>a{font:800 calc(22 * var(--u)) 'Playfair Display',serif;color:#b0102a;text-transform:uppercase;line-height:calc(44 * var(--u));white-space:nowrap}
[data-bz-node="main-nav"],[data-bz-node="main-nav"] .bz-menu-wrap,[data-bz-node="main-nav"] .bz-menu{width:100%;display:block}
@media (min-width:900px){
 [data-bz-node="header"]{height:calc(272 * var(--u))}
 [data-bz-node="header-brand"]{position:absolute;left:calc(22 * var(--u));top:calc(22 * var(--u));width:calc(170 * var(--u))}
 [data-bz-node="header-info"]{position:absolute;right:calc(24 * var(--u));top:calc(47 * var(--u));width:calc(578 * var(--u))}
 [data-bz-node="header-nav-row"]{position:absolute;left:calc(41 * var(--u));right:calc(47 * var(--u));bottom:0}
}
[data-bz-node="sell-row"],[data-bz-node="news-row"]{margin-left:calc(42 * var(--u));margin-right:calc(42 * var(--u))}
[data-bz-node="sell-btn"] .bz-btn,[data-bz-node="news-btn"] .bz-btn,[data-bz-node="news-h"]{display:flex;align-items:center;justify-content:center;width:100%;height:calc(62 * var(--u));background:#8b0000;border-radius:calc(12 * var(--u));color:#fff;font:800 calc(38 * var(--u)) 'Playfair Display',serif;letter-spacing:.06em;text-transform:uppercase;border:0;padding:0;margin:0;box-shadow:none;line-height:calc(62 * var(--u))}
[data-bz-node="sell-btn"] .bz-btn,[data-bz-node="news-btn"] .bz-btn{text-decoration:none}
[data-bz-node="sell-row"]{margin-top:calc(47 * var(--u));height:calc(62 * var(--u))}
[data-bz-node="sell-row"] .bz-col,[data-bz-node="sell-row"] .bz-block,[data-bz-node="sell-row"] .bz-buttons,[data-bz-node="news-row"] .bz-col,[data-bz-node="news-row"] .bz-block,[data-bz-node="news-row"] .bz-buttons{margin:0;padding:0;display:block}
[data-bz-node="info-row"]{height:calc(264 * var(--u));overflow:hidden;margin:calc(40 * var(--u)) 0 0;padding:0 calc(222 * var(--u))}
[data-bz-node="hours-h"],[data-bz-node="contact-h"]{font:800 calc(36 * var(--u)) 'Playfair Display',serif;letter-spacing:.14em;word-spacing:.35em;line-height:1.2;text-transform:uppercase;color:#1a1a6e;margin:0 calc(38 * var(--u)) calc(12 * var(--u)) 0;padding-bottom:calc(14 * var(--u));border-bottom:calc(4 * var(--u)) solid #8b0000}
[data-bz-node="contact-h"]{margin:0 0 calc(12 * var(--u)) calc(39 * var(--u));border-bottom-color:#c0113f}
[data-bz-node="hours-h"] *,[data-bz-node="contact-h"] *{font:inherit;letter-spacing:inherit;word-spacing:inherit;color:inherit;margin:0}
[data-bz-node="hours-t"] p,[data-bz-node="contact-t"] p{margin:0 0 calc(44 * var(--u));font:400 calc(20 * var(--u))/1.15 'Montserrat',sans-serif;letter-spacing:.06em;color:#4a4a5a;text-align:center}
[data-bz-node="hours-t"] strong,[data-bz-node="contact-t"] strong{display:block;font-weight:700;color:#1a1a6e;text-transform:uppercase}
[data-bz-node="news-row"]{margin-bottom:calc(24 * var(--u));height:calc(62 * var(--u))}
[data-bz-node="news-h"],[data-bz-node="news-h"] *{line-height:calc(62 * var(--u))!important;padding:0}
[data-bz-node="news-h"] *{letter-spacing:.06em;margin:0;position:relative;top:calc(3 * var(--u))}
[data-bz-node="map-row"]{border-top:calc(12 * var(--u)) solid #8b0000;border-bottom:calc(12 * var(--u)) solid #8b0000}
[data-bz-node="map"]{height:calc(176 * var(--u));overflow:hidden}
[data-bz-node="map"],[data-bz-node="map"] *{border:0!important;border-radius:0!important;box-shadow:none!important}
[data-bz-node="header-brand"],[data-bz-node="header-brand"] .bz-block,[data-bz-node="header-brand"] .bz-brand,[data-bz-node="header-nav-row"],[data-bz-node="header-nav"],[data-bz-node="main-nav"],[data-bz-node="main-nav"] .bz-menu-wrap,[data-bz-node="main-nav"] .bz-menu,[data-bz-node="main-nav"] .bz-nav{margin:0!important;padding:0!important}
[data-bz-node="header-brand"] .bz-logo__img{display:block}
[data-bz-node="main-nav"] .bz-navitem{height:calc(46 * var(--u))}
[data-bz-node="main-nav"] .bz-navitem>a{display:block;line-height:calc(46 * var(--u))}
[data-bz-node="map-row"] .bz-col,[data-bz-node="map-row"] .bz-block,[data-bz-node="map"]{margin:0!important;padding:0!important;display:block}
[data-bz-node="news-btn"],[data-bz-node="news-btn"] *,[data-bz-node="sell-btn"],[data-bz-node="sell-btn"] *{margin-top:0!important;margin-bottom:0!important;padding-top:0!important;padding-bottom:0!important}
